  function translateNodes(root) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      const original = node.textContent.trim();
      if (translations[original]) node.textContent = node.textContent.replace(original, translations[original]);
    }
  }

  function start() {
    translateNodes(document.body);
    const observer = new MutationObserver(records => {
      for (const record of records) {
        for (const addedNode of record.addedNodes) {
          if (addedNode.nodeType === Node.TEXT_NODE) {
            const original = addedNode.textContent.trim();
            if (translations[original]) addedNode.textContent = addedNode.textContent.replace(original, translations[original]);
          } else if (addedNode.nodeType === Node.ELEMENT_NODE) {
            translateNodes(addedNode);
          }
        }
      }
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === 'complete') start();
  else window.addEventListener('load', start, { once: true });
